"use client";
import{ResponsiveContainer,AreaChart,Area,XAxis,YAxis,CartesianGrid,Tooltip,Legend}from'recharts';import{generation}from'@/data/metrics';export default function MetricsChart(){return <div className='h-72'><ResponsiveContainer width='100%' height='100%'><AreaChart data={generation}><defs><linearGradient id='g' x1='0' y1='0' x2='0' y2='1'><stop offset='5%' stopColor='#0F5A46' stopOpacity={.35}/><stop offset='95%' stopColor='#0F5A46' stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray='3 3' opacity={.2}/><XAxis dataKey='day'/><YAxis/><Tooltip/><Legend/><Area type='monotone' dataKey='solar' stroke='#0F5A46' fill='url(#g)'/><Area type='monotone' dataKey='wind' stroke='#38bdf8' fillOpacity={0}/></AreaChart></ResponsiveContainer></div>}
